func extractSkipReason(output []string) string {
	for _, line := range output {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "--- SKIP") || strings.HasPrefix(trimmed, "=== RUN") {
			continue
		}
